}

.logo a {
  text-decoration: none;
}

.nav-links {
  display: flex;
  list-style: none;
  gap: 2rem;
}

.nav-links a {
  text-decoration: none;
  color: var(--color-text);
  font-weight: 500;
  font-size: 0.9rem;
  text-transform: uppercase;
  letter-spacing: 1px;
  transition: color 0.2s;
}

.nav-links a:hover {
  color: var(--color-accent);
}

.header-actions {
  display: flex;
  gap: 1rem;
}

.icon-btn {
  background: none;
