  --color-bg: #ffffff;
  --color-text: #1a1a1a;
  --color-text-muted: #666666;
  --color-primary: #1a1a1a;
  --color-secondary: #f4f4f4;
  --color-accent: #8b6240; /* Darker for better contrast: 5.4:1 on white */
  --color-accent-light: #fdf8f3;
  --color-border: #e5e5e5;
  --color-focus: #0066cc;

  --font-main: 'Inter', system-ui, -apple-system, sans-serif;
  --container-width: 1200px;
  --spacing-xs: 0.5rem;
  --spacing-sm: 1rem;
  --spacing-md: 2rem;
  --spacing-lg: 4rem;
  --spacing-xl: 6rem;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: var(--font-main);
  background-color: var(--color-bg);
  color: var(--color-text);
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
}

/* Accessibility */
.skip-link {
  position: absolute;
  top: -100px;
  left: 0;
  background: var(--color-primary);
  color: white;
  padding: 1rem;
  z-index: 1000;
  text-decoration: none;
  transition: top 0.2s;
}

.skip-link:focus {
  top: 0;
  outline: 3px solid var(--color-focus);
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  border: 0;
}

/* Layout */
.container {
  max-width: var(--container-width);
  margin: 0 auto;
  padding: 0 var(--spacing-md);
}

/* Header */
.site-header {
  border-bottom: 1px solid var(--color-border);
  position: sticky;
  top: 0;
  background: var(--color-bg);
  z-index: 100;
  padding: 1rem 0;
}

.site-header .container {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.logo-text {
  font-size: 1.5rem;
  font-weight: 800;
  letter-spacing: 2px;
  color: var(--color-primary);
  text-decoration: none;
}

.logo a {
  text-decoration: none;
}

.nav-links {
  display: flex;
  list-style: none;
  gap: 2rem;
}

.nav-links a {
  text-decoration: none;
  color: var(--color-text);
  font-weight: 500;
  font-size: 0.9rem;
  text-transform: uppercase;
  letter-spacing: 1px;
  transition: color 0.2s;
}

.nav-links a:hover {
  color: var(--color-accent);
}

.header-actions {
  display: flex;
  gap: 1rem;
}

.icon-btn {
  background: none;
  border: none;
  cursor: pointer;
  padding: 0.5rem;
  color: var(--color-text);
  transition: transform 0.2s;
}

.icon-btn:hover {
  transform: translateY(-2px);
}

/* Hero */
.hero-section {
  background-color: var(--color-secondary);
  padding: var(--spacing-xl) 0;
  overflow: hidden;
}

.hero-content {
  max-width: 600px;
}

.hero-eyebrow {
  display: block;
  font-size: 0.9rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 2px;
  margin-bottom: 1rem;
  color: var(--color-accent);
}

.hero-section h1 {
  font-size: 4rem;
  line-height: 1.1;
  margin-bottom: 1.5rem;
  font-weight: 800;
}

.hero-section p {
  font-size: 1.25rem;
  color: var(--color-text-muted);
  margin-bottom: 2.5rem;
}

.hero-cta {
  display: flex;
  gap: 1rem;
}

/* Buttons */
.btn {
  display: inline-block;
  padding: 1rem 2rem;
  font-weight: 600;
  text-decoration: none;
  text-transform: uppercase;
  letter-spacing: 1px;
  font-size: 0.8rem;
  transition: all 0.3s ease;
  cursor: pointer;
  border-radius: 0;
}

.btn-primary {
  background-color: var(--color-primary);
  color: white;
  border: 1px solid var(--color-primary);
}

.btn-primary:hover {
  background-color: transparent;
  color: var(--color-primary);
}

.btn-secondary {
  background-color: transparent;
  color: var(--color-primary);
  border: 1px solid var(--color-primary);
}

.btn-secondary:hover {
  background-color: var(--color-primary);
  color: white;
}

.btn-outline {
  background-color: transparent;
  color: var(--color-primary);
  border: 1px solid var(--color-border);
  width: 100%;
}

.btn-outline:hover {
  border-color: var(--color-primary);
  background-color: var(--color-primary);
  color: white;
}

.btn-accent {
  background-color: var(--color-accent);
  color: white;
  border: 1px solid var(--color-accent);
}

.btn-accent:hover {
  background-color: #725034;
  color: white;
}

.btn-added {
  background-color: #2e7d32 !important;
  color: white !important;
  border-color: #2e7d32 !important;
}

/* Featured Products */
.featured-products {
  padding: var(--spacing-lg) 0;
}

.section-header {
  display: flex;
  justify-content: space-between;
  align-items: flex-end;
  margin-bottom: var(--spacing-md);
}

.section-header h2 {
  font-size: 2rem;
}

.view-all {
  color: var(--color-text);
  text-decoration: none;
  font-weight: 600;
  border-bottom: 1px solid var(--color-text);
}

.product-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
  gap: 2rem;
}

.product-card {
  transition: transform 0.3s ease;
}

.product-image {
  aspect-ratio: 3/4;
  background-color: var(--color-secondary);
  margin-bottom: 1rem;
  overflow: hidden;
}

.product-image img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform 0.5s ease;
}

.product-card:hover .product-image img {
  transform: scale(1.05);
}

.product-info h3 {
  font-size: 1rem;
  margin-bottom: 0.5rem;
}

.product-info h3 a {
  text-decoration: none;
  color: var(--color-text);
}

.product-info h3 a:hover {
  text-decoration: underline;
}

.product-price {
  font-weight: 600;
  margin-bottom: 1rem;
  color: var(--color-text-muted);
}

/* Deals Section */
.deals-section {
  padding: var(--spacing-lg) 0;
}

.deals-banner {
  background-color: var(--color-primary);
  color: white;
  padding: var(--spacing-lg);
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 2rem;
}

.deals-content {
  max-width: 500px;
}

.deals-content h2 {
  font-size: 2.5rem;
  margin-bottom: 1rem;
}

.deals-timer {
  background: rgba(255, 255, 255, 0.1);
  padding: 1.5rem;
  border-radius: 4px;
}

.deals-timer p {
  font-family: monospace;
  font-size: 1.5rem;
  font-weight: 700;
}

/* Editorial */
.editorial-section {
  padding: var(--spacing-lg) 0;
}

.editorial-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  align-items: center;
  gap: 4rem;
}

.editorial-main h2 {
  font-size: 3rem;
  margin-bottom: 1.5rem;
}

.editorial-main p {
  font-size: 1.1rem;
  color: var(--color-text-muted);
  margin-bottom: 2rem;
}

.link-arrow {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  text-decoration: none;
  color: var(--color-text);
  font-weight: 700;
  font-size: 1rem;
}

.editorial-image img {
  width: 100%;
  height: auto;
  display: block;
}

/* Footer */
.site-footer {
  background-color: var(--color-bg);
  border-top: 1px solid var(--color-border);
  padding: var(--spacing-lg) 0 var(--spacing-md);
}

.footer-grid {
  display: grid;
  grid-template-columns: 1fr 2fr;
  gap: 4rem;
  margin-bottom: 4rem;
}

.footer-brand p {
  margin-top: 1rem;
  color: var(--color-text-muted);
  max-width: 300px;
