.site-footer {
  background-color: var(--color-bg);
  border-top: 1px solid var(--color-border);
  padding: var(--spacing-lg) 0 var(--spacing-md);
}

.footer-grid {
  display: grid;
  grid-template-columns: 1fr 2fr;
  gap: 4rem;
  margin-bottom: 4rem;
}

.footer-brand p {
  margin-top: 1rem;
  color: var(--color-text-muted);
  max-width: 300px;
}

.footer-nav {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 2rem;
}

.footer-col h3 {
  font-size: 0.8rem;
  text-transform: uppercase;
  letter-spacing: 2px;
  margin-bottom: 1.5rem;
}

.footer-col ul {
  list-style: none;
}

.footer-col li {
  margin-bottom: 0.75rem;
}

.footer-col a {
  text-decoration: none;
  color: var(--color-text-muted);
  font-size: 0.9rem;
  transition: color 0.2s;
}

.footer-col a:hover {
  color: var(--color-primary);
}

.footer-bottom {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding-top: 2rem;
  border-top: 1px solid var(--color-border);
  color: var(--color-text-muted);
  font-size: 0.8rem;
}

.social-links {
  display: flex;
  gap: 1.5rem;
}

.social-links a {
  color: var(--color-text-muted);
  transition: color 0.2s;
}

.social-links a:hover {
  color: var(--color-primary);
}

/* Focus States */
:focus-visible {
  outline: 3px solid var(--color-focus);
  outline-offset: 2px;
}

