function initMobileMenu() {
  const toggle = document.querySelector('.mobile-menu-toggle');
  const nav = document.getElementById('primary-nav');

  if (!toggle || !nav) return;

  toggle.addEventListener('click', () => {
    const expanded = toggle.getAttribute('aria-expanded') === 'true';
    toggle.setAttribute('aria-expanded', !expanded);
    nav.classList.toggle('is-open');

    // Prevent scrolling when menu is open
    if (!expanded) {
      document.body.style.overflow = 'hidden';
    } else {
      document.body.style.overflow = '';
    }
  });

  // Close menu when clicking a link
  nav.addEventListener('click', (e) => {
    if (e.target.tagName === 'A') {
      closeMenu();
    }
  });

  // Close menu with Escape key
  document.addEventListener('keydown', (e) => {
    if (e.key === 'Escape' && nav.classList.contains('is-open')) {
      closeMenu();
      toggle.focus();
    }
  });

  function closeMenu() {
    toggle.setAttribute('aria-expanded', 'false');
    nav.classList.remove('is-open');
    document.body.style.overflow = '';
  }
}

/**
 * Initializes a simple countdown timer for the deals section
 */
function initTimer() {
  const timerElement = document.getElementById('timer');
  if (!timerElement) return;

  let hours = 48;
  let minutes = 0;
  let seconds = 0;

  const updateTimer = () => {
    if (seconds > 0) {
      seconds--;
    } else if (minutes > 0) {
      minutes--;
      seconds = 59;
    } else if (hours > 0) {
      hours--;
      minutes = 59;
      seconds = 59;
    }

    const h = String(hours).padStart(2, '0');
    const m = String(minutes).padStart(2, '0');
    const s = String(seconds).padStart(2, '0');

    timerElement.textContent = `${h}:${m}:${s}`;
  };

  setInterval(updateTimer, 1000);
}

/**
 * Handles "Add to Cart" button clicks and provides feedback
 */
function initAddToCart() {
  const cartButtons = document.querySelectorAll('button[aria-label^="Add to cart"]');
  const cartIcon = document.querySelector('button[aria-label^="Cart"]');
  let cartCount = 0;

  // Create a live region for status messages if it doesn't exist
  let statusRegion = document.getElementById('cart-status');
  if (!statusRegion) {
    statusRegion = document.createElement('div');
    statusRegion.id = 'cart-status';
    statusRegion.setAttribute('aria-live', 'polite');
    statusRegion.classList.add('sr-only');
    document.body.appendChild(statusRegion);
  }

  cartButtons.forEach(button => {
    button.addEventListener('click', () => {
      cartCount++;
      const productName = button.getAttribute('aria-label').replace('Add to cart: ', '');

      // Update cart icon
      cartIcon.setAttribute('aria-label', `Cart, ${cartCount} items`);

      // Update status region for AT
      statusRegion.textContent = `Added ${productName} to your cart. Total items: ${cartCount}.`;

      // Visual feedback on button
      const originalText = button.textContent;
      button.textContent = 'Added!';
      button.classList.add('btn-added');
      button.disabled = true;

      setTimeout(() => {
        button.textContent = originalText;
        button.classList.remove('btn-added');
        button.disabled = false;
      }, 2000);
    });
  });
}
