const playwright = require('playwright');
const fs = require('fs');
const path = require('path');

(async () => {
  const browser = await playwright.chromium.launch();
  const page = await browser.newPage();

  // Load the file
  const filePath = path.resolve('index.html');
  const content = fs.readFileSync(filePath, 'utf8');

  // Inject CSS and JS if needed, but here they are external. 
  // For a standalone check, we can just load the file via file:// URL if possible, 
  // or set content. Since there are external files, setContent might not find them 
  // unless we use a local server or adjust paths.
  // Let's use a simple file server approach or just read them and inject.

  const style = fs.readFileSync('style.css', 'utf8');
  const script = fs.readFileSync('script.js', 'utf8');

  await page.setContent(content);
  await page.addStyleTag({ content: style });
  await page.addScriptTag({ content: script });

  // Inject axe
  const axeSource = fs.readFileSync('node_modules/axe-core/axe.min.js', 'utf8');
  await page.addScriptTag({ content: axeSource });

  const results = await page.evaluate(async () => {
    return await window.axe.run();
  });

  await browser.close();

  const wcag = results.violations.filter(v => !v.tags.includes('best-practice'));
  const bp = results.violations.filter(v => v.tags.includes('best-practice'));

  console.log(JSON.stringify({
    wcag: wcag.map(v => ({ id: v.id, impact: v.impact, description: v.description, targets: v.nodes.map(n => n.target) })),
    bp: bp.map(v => ({ id: v.id, targets: v.nodes.map(n => n.target) }))
  }, null, 2));

  process.exit(wcag.length > 0 ? 1 : 0);
